<script setup lang="ts">
// ConfirmAction (generated by engineering-platform frontend-enterprise-management asset)
// Destructive/risky actions (disable, delete) must confirm before firing.
// Usage: <ConfirmAction title="Disable user" message="..." @confirm="..."><button/></ConfirmAction>

const props = withDefaults(
  defineProps<{ title: string; message?: string; confirmText?: string }>(),
  {
    message: '',
    confirmText: 'Confirm',
  },
);
void props;
const emit = defineEmits<{ confirm: [] }>();
</script>

<template>
  <el-popconfirm
    :title="title"
    :confirm-button-text="confirmText"
    cancel-button-text="Cancel"
    width="280"
    @confirm="emit('confirm')"
  >
    <template #reference>
      <slot />
    </template>
  </el-popconfirm>
</template>
